window.products.push({"id":959836,"name":"World Of Judaica Jeweled Spice Box with Flowers and Peacock in Blue and Amber","category":"homeandappliances","retail price":80.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51uNrAuY+vL._AC_.jpg","description":"This elegant spice box will make your havdalah even more special! This spice box is decorated in blue and brown and features white and blue flowers decorated with shiny jewels. A blue and white peacock rests on the top of the container, itself decorated with three jewels on its head and many more gold jewels on the length of its tail. This havdalah set would be a great housewarming present!","images":["https://m.media-amazon.com/images/I/51uNrAuY+vL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"World Of Judaica","source_asin":"B008EJNGDM","category_path":"Home & Kitchen"},"sku":"BM-959836","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B008EJNGDM","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B008EJNGDM","price_pending":true,"merchant_ready":false});
